        org.springframework.test.util.ReflectionTestUtils.setField(app.getBean(CongeNotificationService.class),"mailEnabled",false);
        org.mockito.Mockito.reset(app.getBean(org.springframework.mail.javamail.JavaMailSender.class));
        execute("TRUNCATE ba_utilisateur,ba_departement,ba_service,ba_conge_politique,ba_conge_calendrier,ba_conge_couverture,ba_conge_operation,ba_rh_circuit CASCADE");
        execute("INSERT INTO ba_departement(id,nom,created_by,created_date) VALUES ('dept','D','test',now()),('foreign','F','test',now())");execute("INSERT INTO ba_service(id,nom,departement_id,created_by,created_date) VALUES ('s1','S1','dept','test',now()),('s2','S2','dept','test',now())");
        fixture("agent","AGENT","dept","s1");fixture("agent2","AGENT","dept","s2");fixture("chief","CHEF_SERVICE","dept","s1");fixture("peer","CHEF_SERVICE","dept","s2");fixture("foreign-chief","CHEF_SERVICE","foreign",null);fixture("director","DIRECTEUR","dept",null);fixture("ops","DIRECTEUR_GENERAL_ADJOINT",null,null);fixture("dev","DIRECTEUR_GENERAL_ADJOINT",null,null);fixture("dg","DIRECTEUR_GENERAL",null,null);fixture("rh","AGENT",null,null);fixture("admin","AGENT",null,null);
        execute("INSERT INTO ba_user_roles(user_id,role_id) SELECT 'rh',id FROM ba_role WHERE code IN ('CONGES_POLITIQUES','CONGES_DROITS','CONGES_PIECES','CONGES_EXPORTER','CONGES_PLANNING','CONGES_AUDITER','CONGES_ANNULER') ON CONFLICT DO NOTHING");execute("INSERT INTO ba_user_roles(user_id,role_id) VALUES ('admin','role-ba-admin')");
        execute("INSERT INTO ba_dga_pole_validateur(id,pole,dga_id,date_debut,actif,created_by,created_date) VALUES ('ops-pole','OPERATIONS','ops',CURRENT_DATE-1,true,'test',now()),('dev-pole','DEVELOPPEMENT','dev',CURRENT_DATE-1,true,'test',now())");
        var c=new LinkedHashMap<String,Object>();c.put("nom","Calendrier de recette, tous les jours explicitement travailles");c.put("debutEffet",today.minusYears(2));c.put("finEffet",today.plusYears(2));c.put("sourceRh","Fixture de test, sans valeur de politique bancaire");c.put("regles",CongeCalculServiceTest.calendar());calendarId=post("rh","calendriers",c,201).path("id").asText();post("rh","calendriers/"+calendarId+"/confirmer",confirmation(),200);
        configure(CongeCalculServiceTest.policy());assignmentId=assign("agent");rightId=open(assignmentId,today.withDayOfYear(1),today.withMonth(12).withDayOfMonth(31),null).path("droitId").asText();org.mockito.Mockito.reset(app.getBean(BaMailService.class));
