    @AfterAll void close()throws Exception{if(app!=null)app.close();if(sql!=null)try{if(schema!=null&&schema.matches("bsic_conges_test_[0-9a-f]{32}"))execute("DROP SCHEMA "+schema+" CASCADE");}finally{sql.close();}}
    private void configure(Politique p)throws Exception{var body=new LinkedHashMap<String,Object>();body.put("typeCode","ANNUEL_TEST");body.put("libelle","Conge annuel de recette");body.put("categorie","CONGE_ANNUEL");body.put("debutEffet",today.minusYears(2));body.put("finEffet",today.plusYears(2));body.put("sourceRh","Fixture de test explicite, aucun droit legal presume");body.put("regles",p);policyId=post("rh","politiques",body,201).path("id").asText();post("rh","politiques/"+policyId+"/confirmer",confirmation(),200);}
    private String assign(String agent)throws Exception{return post("rh","affectations",Map.of("agentId",agent,"politiqueId",policyId,"calendrierId",calendarId,"debut",today.minusYears(2),"fin",today.plusYears(2),"justification","Test"),201).path("id").asText();}
    private JsonNode open(String assignment,LocalDate from,LocalDate to,LocalDate expiry)throws Exception{var b=new LinkedHashMap<String,Object>();b.put("affectationId",assignment);b.put("debut",from);b.put("fin",to);b.put("expiration",expiry);b.put("cle",UUID.randomUUID().toString());b.put("source","Test");b.put("justification","Test");return post("rh","droits/periodes",b,201);}
    private Map<String,Object> input(LocalDate from,LocalDate to){var b=new LinkedHashMap<String,Object>();b.put("typeCode","ANNUEL_TEST");b.put("debut",from.toString());b.put("fin",to.toString());b.put("portionDebut","JOURNEE");b.put("portionFin","JOURNEE");b.put("motif","Motif sensible de recette");return b;}
    private JsonNode draft(String actor,LocalDate from,LocalDate to)throws Exception{return post(actor,"demandes",input(from,to),201);}
    private JsonNode submit(String actor,JsonNode d)throws Exception{return act(actor,d,"soumettre",Map.of(),200);}
    private JsonNode act(String actor,JsonNode d,String action,Map<String,Object> extra,int status)throws Exception{var b=operation(d);b.putAll(extra);return post(actor,"demandes/"+d.path("id").asText()+"/"+action,b,status);}
    private Map<String,Object> operation(JsonNode d){var b=new LinkedHashMap<String,Object>();b.put("version",d.path("version").asLong());b.put("cle",UUID.randomUUID().toString());b.put("etape",d.at("/circuit/etapeCourante").asInt());b.put("justification","Recette");return b;}
    private JsonNode approve(JsonNode d)throws Exception{while(d.path("etat").asText().equals("EN_ATTENTE")){String actor=switch(d.at("/circuit/etapes/"+d.at("/circuit/etapeCourante").asInt()+"/type").asText()){case "CHEF_SERVICE"->"peer";case "DIRECTEUR"->"director";case "DG"->"dg";case "AUTRE_DGA"->d.path("agentId").asText().equals("ops")?"dev":"ops";default->"ops";};d=act(actor,d,"approuver",Map.of(),200);}return d;}
    private JsonNode balance()throws Exception{return get("agent","mes-soldes",200).get(0);}

    @Test void policyWithoutDgChoiceDefaultsToOptionalAndOneDgaCommitsTheDebit() throws Exception {
        execute("TRUNCATE ba_conge_politique CASCADE");
        var rules=(com.fasterxml.jackson.databind.node.ObjectNode)json.valueToTree(CongeCalculServiceTest.policy());rules.remove("dgObligatoire");
        var body=new LinkedHashMap<String,Object>();body.put("typeCode","ANNUEL_TEST");body.put("libelle","Congé de recette sans DG");body.put("categorie","CONGE_ANNUEL");body.put("debutEffet",today.minusYears(2));body.put("finEffet",today.plusYears(2));body.put("sourceRh","Recette : DG facultatif");body.put("regles",rules);
        var policy=post("rh","politiques",body,201);assertThat(policy.at("/regles/dgObligatoire").asBoolean()).isFalse();policyId=policy.path("id").asText();post("rh","politiques/"+policyId+"/confirmer",confirmation(),200);
        String assignment=assign("agent");open(assignment,today.withDayOfYear(1),today.withMonth(12).withDayOfMonth(31),null);
        execute("UPDATE ba_utilisateur SET activated=false WHERE id IN ('dg','dev')");
        var simulation=post("agent","simulation",input(today.plusDays(3),today.plusDays(3)),200);assertThat(simulation.path("blocages").size()).isZero();
        assertThat(simulation.at("/circuit/dgObligatoire").asBoolean()).isFalse();
        var d=submit("agent",draft("agent",today.plusDays(3),today.plusDays(3)));assertThat(d.at("/circuit/etapes").findValuesAsText("type")).containsExactly("CHEF_SERVICE","DIRECTEUR","DGA");
        act("agent",d,"approuver",Map.of(),403);act("ops",d,"approuver",Map.of(),403);
        d=act("peer",d,"approuver",Map.of(),200);d=act("director",d,"approuver",Map.of(),200);
        assertThat(d.path("etat").asText()).isEqualTo("EN_ATTENTE");assertThat(new java.math.BigDecimal(balance().path("reserves").asText())).isEqualByComparingTo("1");assertThat(new java.math.BigDecimal(balance().path("debites").asText())).isEqualByComparingTo("0");
        assertThat(d.at("/circuit/etapes/2/validateurs").size()).isEqualTo(1);
        var pending=d;d=act("ops",d,"approuver",Map.of(),200);assertThat(d.path("etat").asText()).isEqualTo("APPROUVEE");
        act("ops",pending,"approuver",Map.of(),409);assertThat(count("SELECT count(*) FROM ba_conge_mouvement WHERE nature='DEBIT'")).isEqualTo(1);
        assertThat(new java.math.BigDecimal(balance().path("reserves").asText())).isEqualByComparingTo("0");assertThat(new java.math.BigDecimal(balance().path("debites").asText())).isEqualByComparingTo("1");
        execute("UPDATE ba_utilisateur SET activated=false WHERE id='ops'");
        simulation=post("agent","simulation",input(today.plusDays(8),today.plusDays(8)),200);assertThat(simulation.path("blocages").toString()).contains("DGA");
        var blocked=draft("agent",today.plusDays(8),today.plusDays(8));act("agent",blocked,"soumettre",Map.of(),409);
        assertThat(count("SELECT count(*) FROM ba_conge_mouvement WHERE nature='RESERVATION'")).isEqualTo(1);assertThat(count("SELECT count(*) FROM ba_autorisation_absence")).isZero();
    }

    @Test void reservationDebitIdempotenceAndDgRequirementWithoutTouchingAbsenceCounter()throws Exception{
        JsonNode d=submit("agent",draft("agent",today.plusDays(3),today.plusDays(4)));assertThat(balance().path("reserves").asText()).isEqualTo("2.0000");assertThat(count("SELECT count(*) FROM ba_autorisation_absence")).isZero();
        act("agent",d,"approuver",Map.of(),403);act("foreign-chief",d,"approuver",Map.of(),403);act("admin",d,"approuver",Map.of(),403);
        var body=operation(d);String path="demandes/"+d.path("id").asText()+"/approuver";JsonNode next=post("peer",path,body,200);assertThat(post("peer",path,body,200).path("version").asLong()).isEqualTo(next.path("version").asLong());act("chief",d,"approuver",Map.of(),409);
        next=act("director",next,"approuver",Map.of(),200);next=act("ops",next,"approuver",Map.of(),200);assertThat(next.path("etat").asText()).isEqualTo("EN_ATTENTE");assertThat(balance().path("debites").asText()).isEqualTo("0");
        next=act("dg",next,"approuver",Map.of(),200);assertThat(next.path("etat").asText()).isEqualTo("APPROUVEE");assertThat(new java.math.BigDecimal(balance().path("reserves").asText())).isEqualByComparingTo("0");assertThat(balance().path("debites").asText()).isEqualTo("2.0000");assertThat(balance().path("approuvesAVenir").asText()).isEqualTo("2.0000");assertThat(count("SELECT count(*) FROM ba_conge_mouvement WHERE nature='DEBIT'")).isEqualTo(1);verifyNoInteractions(app.getBean(BaMailService.class));
    }
    @Test void concurrentChiefsMakeOnlyOneTransition()throws Exception{JsonNode d=submit("agent",draft("agent",today.plusDays(3),today.plusDays(3)));List<Integer> codes=race(()->call("peer","POST","demandes/"+d.path("id").asText()+"/approuver",operation(d)).statusCode(),()->call("chief","POST","demandes/"+d.path("id").asText()+"/approuver",operation(d)).statusCode());assertThat(codes).containsExactlyInAnyOrder(200,409);assertThat(count("SELECT jsonb_array_length(historique) FROM ba_rh_circuit")).isEqualTo(1);assertThat(count("SELECT count(*) FROM ba_conge_mouvement WHERE nature='DEBIT'")).isZero();}
    @Test void withdrawalAndDefinitiveRejectionReleaseReservation()throws Exception{var d=submit("agent",draft("agent",today.plusDays(3),today.plusDays(3)));act("agent",d,"retirer",Map.of(),200);assertThat(new java.math.BigDecimal(balance().path("reserves").asText())).isEqualByComparingTo("0");d=submit("agent",draft("agent",today.plusDays(3),today.plusDays(3)));act("peer",d,"rejeter",Map.of(),200);assertThat(new java.math.BigDecimal(balance().path("disponible").asText())).isEqualByComparingTo("20");}
    @Test void technicalAdministratorCannotReadConfigureOrExportAndMotifHiddenFromValidators()throws Exception{var d=submit("agent",draft("agent",today.plusDays(3),today.plusDays(3)));assertThat(get("peer","demandes/"+d.path("id").asText(),200).path("motif").isNull()).isTrue();get("foreign-chief","demandes/"+d.path("id").asText(),403);get("admin","demandes/"+d.path("id").asText(),403);get("admin","politiques",403);get("admin","export?debut="+today+"&fin="+today.plusDays(30),403);get("rh","export?debut="+today+"&fin="+today.plusDays(30),200);assertThat(call(null,"GET","mes-soldes",null).statusCode()).isEqualTo(401);}
    @Test void cancellationRestoresOnceAndDocumentReflectsActualApproval()throws Exception{var d=submit("agent",draft("agent",today.plusDays(3),today.plusDays(4)));get("agent","demandes/"+d.path("id").asText()+"/document",409);d=approve(d);assertThat(call("agent","GET","demandes/"+d.path("id").asText()+"/document",null).body()).startsWith("%PDF");d=act("rh",d,"annuler",Map.of(),200);assertThat(d.path("etat").asText()).isEqualTo("ANNULEE");assertThat(new java.math.BigDecimal(balance().path("debites").asText())).isEqualByComparingTo("0");assertThat(new java.math.BigDecimal(balance().path("disponible").asText())).isEqualByComparingTo("20");act("rh",d,"annuler",Map.of(),409);}
    @Test void approvedRevisionSurvivesModificationAndDeltaReservationAvoidsDoubleDebit()throws Exception{var original=approve(submit("agent",draft("agent",today.plusDays(3),today.plusDays(4))));var body=input(today.plusDays(3),today.plusDays(5));body.put("remplaceDemandeId",original.path("id").asText());var revision=post("agent","demandes",body,201);revision=submit("agent",revision);assertThat(new java.math.BigDecimal(balance().path("reserves").asText())).isEqualByComparingTo("1");assertThat(new java.math.BigDecimal(balance().path("debites").asText())).isEqualByComparingTo("2");assertThat(get("agent","demandes/"+original.path("id").asText(),200).path("etat").asText()).isEqualTo("APPROUVEE");approve(revision);assertThat(new java.math.BigDecimal(balance().path("debites").asText())).isEqualByComparingTo("3");assertThat(new java.math.BigDecimal(balance().path("reserves").asText())).isEqualByComparingTo("0");assertThat(get("agent","demandes/"+original.path("id").asText(),200).path("etat").asText()).isEqualTo("REMPLACEE");}
    @Test void earlyReturnRestoresOnlyUnusedAfternoonAfterRhControl()throws Exception{var d=approve(submit("agent",draft("agent",today,today.plusDays(1))));d=act("agent",d,"demander-retour",Map.of("dateReprise",today.toString(),"portionReprise","APRES_MIDI"),200);assertThat(new java.math.BigDecimal(balance().path("debites").asText())).isEqualByComparingTo("2");d=act("rh",d,"confirmer-retour",Map.of(),200);assertThat(d.path("retourStatut").asText()).isEqualTo("VALIDEE");assertThat(new java.math.BigDecimal(balance().path("debites").asText())).isEqualByComparingTo("0.5");assertThat(new java.math.BigDecimal(balance().path("pris").asText())).isEqualByComparingTo("0.5");assertThat(get("agent","planning?debut="+today+"&fin="+today,200).get(0).path("fin").asText()).isEqualTo(today.toString());}
    @Test void chiefsDirectorsAndOtherDgaUseTheirOwnFrozenCircuitAndDgCanBeDisabled()throws Exception{execute("TRUNCATE ba_conge_politique CASCADE");var p=CongeCalculServiceTest.policy();p.setDgObligatoire(false);configure(p);for(String actor:List.of("chief","director","ops","dev")){String a=assign(actor);open(a,today.withDayOfYear(1),today.withMonth(12).withDayOfMonth(31),null);var d=submit(actor,draft(actor,today.plusDays(3),today.plusDays(3)));assertThat(d.at("/circuit/etapes/0/type").asText()).isEqualTo(actor.equals("chief")?"DIRECTEUR":actor.equals("director")?"DGA":"AUTRE_DGA");act(actor,d,"approuver",Map.of(),403);if(actor.equals("ops"))act("director",d,"approuver",Map.of(),403);assertThat(approve(d).path("etat").asText()).isEqualTo("APPROUVEE");}String a=assign("dg");open(a,today.withDayOfYear(1),today.withMonth(12).withDayOfMonth(31),null);var d=draft("dg",today.plusDays(3),today.plusDays(3));act("dg",d,"soumettre",Map.of(),409);}
    @Test void concurrentReservationsCannotOverdrawOneCounter()throws Exception{post("rh","droits/ajustements",Map.of("droitId",rightId,"quantite","-19","cle","shrink","source","Test","justification","Test"),200);var a=draft("agent",today.plusDays(3),today.plusDays(3));var b=draft("agent",today.plusDays(5),today.plusDays(5));var codes=race(()->call("agent","POST","demandes/"+a.path("id").asText()+"/soumettre",operation(a)).statusCode(),()->call("agent","POST","demandes/"+b.path("id").asText()+"/soumettre",operation(b)).statusCode());assertThat(codes).containsExactlyInAnyOrder(200,409);assertThat(new java.math.BigDecimal(balance().path("reserves").asText())).isEqualByComparingTo("1");}
    @Test void twoApprovalsCannotBreakConfirmedCoverage()throws Exception{assign("agent2");open(get("rh","affectations",200).get(0).path("id").asText(),today.withDayOfYear(1),today.withMonth(12).withDayOfMonth(31),null);assign("chief");assign("peer");assign("director");var rule=Map.of("granularite","JOURNEE","perimetre","DEPARTEMENT","perimetreId","dept","maximumIndisponibles",1,"minimumParFonction",Map.of(),"groupes",List.of(),"incompatibilites",List.of(),"bloquante",true);var c=post("rh","couverture",Map.of("nom","Test","debut",today,"sourceRh","Test","regles",rule),201);post("rh","couverture/"+c.path("id").asText()+"/confirmer",confirmation(),200);var a=submit("agent",draft("agent",today.plusDays(3),today.plusDays(3)));var b=submit("agent2",draft("agent2",today.plusDays(3),today.plusDays(3)));for(String actor:List.of("peer","director","ops")){a=act(actor,a,"approuver",Map.of(),200);b=act(actor,b,"approuver",Map.of(),200);}final JsonNode aa=a,bb=b;assertThat(race(()->call("dg","POST","demandes/"+aa.path("id").asText()+"/approuver",operation(aa)).statusCode(),()->call("dg","POST","demandes/"+bb.path("id").asText()+"/approuver",operation(bb)).statusCode())).containsExactlyInAnyOrder(200,409);assertThat(count("SELECT count(*) FROM ba_conge_demande WHERE etat='APPROUVEE'")).isEqualTo(1);}
    @Test void overlapWithAbsenceAndOutingCannotBypassApi()throws Exception{execute("INSERT INTO ba_autorisation_absence(id,motif,date_debut,date_fin,nombre_jours,demandeur_id,statut_validation,created_by,created_date,statut) VALUES ('absence','test',CURRENT_DATE+3,CURRENT_DATE+3,1,'agent','VALIDEE','test',now(),'A')");var d=draft("agent",today.plusDays(3),today.plusDays(3));act("agent",d,"soumettre",Map.of(),409);assertThat(new java.math.BigDecimal(balance().path("reserves").asText())).isEqualByComparingTo("0");}
    @Test void calendarSnapshotsSurviveLaterConfigurationAndPiecesRemainPrivate()throws Exception{var d=draft("agent",today.plusDays(3),today.plusDays(3));String id=d.path("id").asText();String boundary="bsicTest";String data="--"+boundary+"\r\nContent-Disposition: form-data; name=\"file\"; filename=\"test.pdf\"\r\nContent-Type: application/pdf\r\n\r\n%PDF-1.4\nfixture\r\n--"+boundary+"--\r\n";var upload=http.send(HttpRequest.newBuilder(URI.create(base+"/api/conges/demandes/"+id+"/pieces")).header("Authorization","Bearer "+tokens.get("agent")).header("Content-Type","multipart/form-data; boundary="+boundary).header("Accept","application/json").POST(HttpRequest.BodyPublishers.ofString(data)).build(),HttpResponse.BodyHandlers.ofString());JsonNode piece=status(upload,200);get("peer","pieces/"+piece.path("id").asText(),403);get("agent2","pieces/"+piece.path("id").asText(),403);assertThat(call("rh","GET","pieces/"+piece.path("id").asText(),null).body()).startsWith("%PDF");d=get("agent","demandes/"+id,200);d=submit("agent",d);execute("UPDATE ba_conge_calendrier SET regles=jsonb_set(regles,'{semaine,0,plages}','[]')");assertThat(new java.math.BigDecimal(get("agent","demandes/"+id,200).at("/calcul/quantite").asText())).isEqualByComparingTo("1");}
    @Test void importSimulationRejectsDoubleCreditThenValidatesIdempotently()throws Exception{execute("TRUNCATE ba_conge_droit CASCADE");var line=Map.of("cle","line1","affectationId",assignmentId,"origineDebut",today.withDayOfYear(1),"origineFin",today.withMonth(12).withDayOfMonth(31),"solde","7.25","justification","Solde arrete rapproche");var payload=Map.of("arrete",today,"source","Reprise recette","lignes",List.of(line));var sim=post("rh","reprise/simuler",payload,200);assertThat(sim.at("/simulation/valide").asBoolean()).isTrue();var confirm=Map.of("importation",payload,"empreinteSimulation",sim.path("empreinte").asText(),"confirmation",confirmation());post("rh","reprise/confirmer",confirm,200);post("rh","reprise/confirmer",confirm,200);assertThat(new java.math.BigDecimal(balance().path("acquis").asText())).isEqualByComparingTo("7.25");assertThat(count("SELECT count(*) FROM ba_conge_mouvement WHERE nature='REPRISE_SOLDE'")).isEqualTo(1);assertThat(post("rh","reprise/simuler",payload,200).at("/simulation/valide").asBoolean()).isFalse();}
    @Test void acquisitionIsIdempotentAndProjectedRightsCannotBeConsumed()throws Exception{execute("TRUNCATE ba_conge_politique CASCADE");var p=CongeCalculServiceTest.policy();p.setAttribution(Attribution.ACQUISITION);p.setDotation(null);p.setFrequence(Frequence.MENSUELLE);p.setAcquisitionParEcheance(new java.math.BigDecimal("2"));configure(p);assignmentId=assign("agent");var r=open(assignmentId,today.withDayOfYear(1),today.withMonth(12).withDayOfMonth(31),null);assertThat(new java.math.BigDecimal(r.path("projetes").asText())).isGreaterThan(java.math.BigDecimal.ZERO);post("rh","droits/traiter-echeances",Map.of(),200);post("rh","droits/traiter-echeances",Map.of(),200);assertThat(new java.math.BigDecimal(balance().path("acquis").asText())).isEqualByComparingTo(new java.math.BigDecimal(r.path("acquis").asText()));post("rh","droits/ajustements",Map.of("droitId",r.path("droitId").asText(),"quantite",new java.math.BigDecimal(r.path("acquis").asText()).negate().toString(),"cle","remove","source","Test","justification","Test"),200);var d=draft("agent",today.plusDays(3),today.plusDays(3));act("agent",d,"soumettre",Map.of(),409);}
    @Test void carriesRetainOriginAndExpireWithoutDoubleCounting()throws Exception{execute("TRUNCATE ba_conge_politique CASCADE");var p=CongeCalculServiceTest.policy();p.setReportAutorise(true);p.setPlafondReport(new java.math.BigDecimal("5"));p.setExpirationReportJours(5);configure(p);String a=assign("agent");String source=open(a,today.minusDays(30),today.minusDays(1),today.plusDays(10)).path("droitId").asText();String target=open(a,today,today.plusDays(30),null).path("droitId").asText();var body=Map.of("sourceDroitId",source,"cibleDroitId",target,"cle","carry","justification","Test");var carry=post("rh","droits/reports",body,200);assertThat(post("rh","droits/reports",body,200).path("droitId").asText()).isEqualTo(carry.path("droitId").asText());assertThat(new java.math.BigDecimal(carry.path("acquis").asText())).isEqualByComparingTo("5");assertThat(carry.path("origineDebut").asText()).isEqualTo(today.minusDays(30).toString());assertThat(count("SELECT count(*) FROM ba_conge_mouvement WHERE nature='REPORT_SORTANT'")).isEqualTo(1);execute("UPDATE ba_conge_droit SET expiration=CURRENT_DATE-1 WHERE id='"+carry.path("droitId").asText()+"'");post("rh","droits/traiter-echeances",Map.of(),200);post("rh","droits/traiter-echeances",Map.of(),200);assertThat(count("SELECT count(*) FROM ba_conge_mouvement WHERE nature='EXPIRATION'")).isEqualTo(1);}
    @Test void futurePeriodAdvanceIsExplicitAndAllocationCrossesTwoOrigins()throws Exception{execute("TRUNCATE ba_conge_politique CASCADE");var p=CongeCalculServiceTest.policy();p.setAnticipationAutorisee(true);p.setPlafondAnticipation(new java.math.BigDecimal("2"));configure(p);String a=assign("agent");LocalDate boundary=today.plusDays(3);open(a,today.minusDays(30),boundary,null);open(a,boundary.plusDays(1),boundary.plusDays(30),null);var s=post("agent","simulation",input(boundary,boundary.plusDays(1)),200);assertThat(s.path("blocages").size()).isZero();assertThat(s.path("droits").size()).isEqualTo(2);assertThat(s.at("/droits/0/droitId").asText()).isNotEqualTo(s.at("/droits/1/droitId").asText());var d=approve(submit("agent",draft("agent",boundary,boundary.plusDays(1))));assertThat(count("SELECT count(*) FROM ba_conge_mouvement WHERE nature='DEBIT'")).isEqualTo(2);}
