    @Test void blockingExpiryPreservesRequestUntilRhAction()throws Exception{execute("TRUNCATE ba_conge_politique CASCADE");var p=CongeCalculServiceTest.policy();p.setExpirationReservation(ExpirationReservation.BLOQUER_ET_SIGNALER);configure(p);String a=assign("agent");String lot=open(a,today.withDayOfYear(1),today.withMonth(12).withDayOfMonth(31),null).path("droitId").asText();var d=submit("agent",draft("agent",today.plusDays(3),today.plusDays(3)));execute("UPDATE ba_conge_droit SET expiration=CURRENT_DATE-1 WHERE id='"+lot+"'");post("rh","droits/traiter-echeances",Map.of(),200);for(String actor:List.of("peer","director","ops"))d=act(actor,d,"approuver",Map.of(),200);act("dg",d,"approuver",Map.of(),409);assertThat(new java.math.BigDecimal(balance().path("reserves").asText())).isEqualByComparingTo("1");d=get("agent","demandes/"+d.path("id").asText(),200);act("agent",d,"retirer",Map.of(),200);assertThat(new java.math.BigDecimal(balance().path("reserves").asText())).isEqualByComparingTo("0");}
    @Test void requiredHandoverIsVisibleInDraftAndNeverTransfersPermissions()throws Exception{execute("TRUNCATE ba_conge_politique CASCADE");var p=CongeCalculServiceTest.policy();p.setPassationRequise(true);p.setRemplacementRequis(true);configure(p);String a=assign("agent");open(a,today.withDayOfYear(1),today.withMonth(12).withDayOfMonth(31),null);var d=draft("agent",today.plusDays(3),today.plusDays(3));act("agent",d,"soumettre",Map.of(),409);long roles=count("SELECT count(*) FROM ba_user_roles WHERE user_id='agent2'");var saved=call("agent","PUT","demandes/"+d.path("id").asText()+"/passation",Map.of("remplacantId","agent2","tachesEtEcheances","Tache a reprendre","contactsUtiles","Contact de recette"));status(saved,200);assertThat(get("agent2","mes-passations",200).size()).isEqualTo(1);post("agent2","demandes/"+d.path("id").asText()+"/passation/accepter",Map.of(),200);d=get("agent","demandes/"+d.path("id").asText(),200);approve(submit("agent",d));assertThat(count("SELECT count(*) FROM ba_user_roles WHERE user_id='agent2'")).isEqualTo(roles);String b=assign("agent2");open(b,today.withDayOfYear(1),today.withMonth(12).withDayOfMonth(31),null);var replacementLeave=draft("agent2",today.plusDays(3),today.plusDays(3));act("agent2",replacementLeave,"soumettre",Map.of(),409);}
    @Test void delegationIsScopedFrozenRevocableAndDecisionKeepsActualSigner()throws Exception{execute("TRUNCATE ba_conge_politique CASCADE");var p=CongeCalculServiceTest.policy();p.setDelegationsAutorisees(true);configure(p);String a=assign("agent");open(a,today.withDayOfYear(1),today.withMonth(12).withDayOfMonth(31),null);var body=Map.of("idDelegant","chief","idDelegue","agent2","roleCode","BA_CHEF_SERVICE","idDepartement","dept","dateDebut",today.minusDays(1),"dateFin",today.plusDays(30),"motif","Interim explicite");post("agent","delegations",body,403);var delegation=post("admin","delegations",body,200);var d=submit("agent",draft("agent",today.plusDays(3),today.plusDays(3)));d=act("agent2",d,"approuver",Map.of(),200);assertThat(d.at("/circuit/historique/0/idSignataire").asText()).isEqualTo("agent2");assertThat(d.at("/circuit/historique/0/idDelegant").asText()).isEqualTo("chief");assertThat(d.at("/circuit/historique/0/idDelegation").asText()).isEqualTo(delegation.path("id").asText());var second=submit("agent",draft("agent",today.plusDays(6),today.plusDays(6)));status(call("admin","DELETE","delegations/"+delegation.path("id").asText(),null),204);act("agent2",second,"approuver",Map.of(),403);}
    @Test void expiredOrForeignDelegationCannotApproveAndRefusalAlternativeDoesNotRelease()throws Exception{execute("TRUNCATE ba_conge_politique CASCADE");var p=CongeCalculServiceTest.policy();p.setDelegationsAutorisees(true);p.setPolitiqueRefus("AUTRES_VALIDATEURS");configure(p);String a=assign("agent");open(a,today.withDayOfYear(1),today.withMonth(12).withDayOfMonth(31),null);post("admin","delegations",Map.of("idDelegant","chief","idDelegue","agent2","roleCode","BA_CHEF_SERVICE","idDepartement","foreign","dateDebut",today.minusDays(2),"dateFin",today.plusDays(1),"motif","Test"),200);var d=submit("agent",draft("agent",today.plusDays(3),today.plusDays(3)));act("agent2",d,"approuver",Map.of(),403);d=act("chief",d,"rejeter",Map.of(),200);assertThat(d.path("etat").asText()).isEqualTo("EN_ATTENTE");assertThat(new java.math.BigDecimal(balance().path("reserves").asText())).isEqualByComparingTo("1");act("chief",d,"approuver",Map.of(),403);d=act("peer",d,"approuver",Map.of(),200);assertThat(d.at("/circuit/etapeCourante").asInt()).isEqualTo(1);}
    @Test void outboxRetriesFailuresWithoutRecreatingBusinessEffects()throws Exception{var d=submit("agent",draft("agent",today.plusDays(3),today.plusDays(3)));long entries=count("SELECT count(*) FROM ba_conge_notification");assertThat(entries).isEqualTo(3);execute("UPDATE ba_utilisateur SET email=username || '@example.test'");var sender=app.getBean(org.springframework.mail.javamail.JavaMailSender.class);doThrow(new org.springframework.mail.MailSendException("Echec simule")).doNothing().when(sender).send(any(org.springframework.mail.SimpleMailMessage.class));var service=app.getBean(CongeNotificationService.class);org.springframework.test.util.ReflectionTestUtils.setField(service,"mailEnabled",true);service.dispatch();assertThat(count("SELECT count(*) FROM ba_conge_notification WHERE envoyee")).isEqualTo(entries-1);execute("UPDATE ba_conge_notification SET prochain_essai=now()-interval '1 minute' WHERE NOT envoyee");service.dispatch();service.dispatch();assertThat(count("SELECT count(*) FROM ba_conge_notification WHERE envoyee")).isEqualTo(entries);assertThat(count("SELECT count(*) FROM ba_conge_notification")).isEqualTo(entries);assertThat(count("SELECT count(*) FROM ba_conge_mouvement WHERE nature='RESERVATION'")).isEqualTo(1);verify(sender,times((int)entries+1)).send(any(org.springframework.mail.SimpleMailMessage.class));}

