    @Test void longRhReferencesAndImportApprovalAreKeptWithoutTruncation()throws Exception{String reason="R".repeat(900);post("rh","calendriers/"+calendarId+"/confirmer",Map.of("confirme",true,"justification",reason),200);assertThat(count("SELECT count(*) FROM ba_log WHERE length(details)>900")).isGreaterThanOrEqualTo(1);execute("TRUNCATE ba_conge_droit CASCADE");var payload=Map.of("arrete",today,"source","S".repeat(1000),"lignes",List.of(Map.of("cle","long","affectationId",assignmentId,"origineDebut",today.withDayOfYear(1),"origineFin",today.withMonth(12).withDayOfMonth(31),"solde","5","justification",reason)));var sim=post("rh","reprise/simuler",payload,200);post("rh","reprise/confirmer",Map.of("importation",payload,"empreinteSimulation",sim.path("empreinte").asText(),"confirmation",Map.of("confirme",true,"justification",reason)),200);assertThat(count("SELECT count(*) FROM ba_conge_mouvement WHERE length(justification)>1800")).isEqualTo(1);}
    private Map<String,Object> confirmation(){return Map.of("confirme",true,"justification","Decision explicite pour la recette uniquement");}
    private void fixture(String id,String fn,String dept,String service)throws Exception{try(var p=sql.prepareStatement("INSERT INTO ba_utilisateur(id,username,password_hash,nom,telephone,fonction,departement_id,service_id,activated,account_locked,created_by,created_date) VALUES (?,?, 'unused',?,?,?,?,?,true,false,'test',now())")){p.setString(1,id);p.setString(2,id);p.setString(3,id);p.setString(4,id);p.setString(5,fn);p.setString(6,dept);p.setString(7,service);p.executeUpdate();}SignatureTestImages.seed(sql,id);execute("INSERT INTO ba_user_roles(user_id,role_id) SELECT '"+id+"',id FROM ba_role WHERE code IN ('BA_CONNECT','CONGES_DEMANDER','CONGES_VALIDER','CONGES_PLANNING')");tokens.put(id,app.getBean(TokenProvider.class).createToken(new UsernamePasswordAuthenticationToken(id,"",List.of(new SimpleGrantedAuthority("BA_CONNECT"))),false).getToken());}
    private JsonNode post(String actor,String path,Object body,int expected)throws Exception{return status(call(actor,"POST",path,body),expected);}
    private JsonNode get(String actor,String path,int expected)throws Exception{return status(call(actor,"GET",path,null),expected);}
    private HttpResponse<String> call(String actor,String method,String path,Object body)throws Exception{var b=HttpRequest.newBuilder(URI.create(base+"/api/conges/"+path)).header("Content-Type","application/json").header("Accept","application/json").header("Idempotency-Key",UUID.randomUUID().toString());if(actor!=null)b.header("Authorization","Bearer "+tokens.get(actor));return http.send(b.method(method,body==null?HttpRequest.BodyPublishers.noBody():HttpRequest.BodyPublishers.ofString(json.writeValueAsString(body))).build(),HttpResponse.BodyHandlers.ofString());}
    private JsonNode status(HttpResponse<String> response,int expected)throws Exception{assertThat(response.statusCode()).as(response.body().substring(0,Math.min(response.body().length(),1500))).isEqualTo(expected);if(!response.headers().firstValue("content-type").orElse("").contains("json"))return json.createObjectNode();return json.readTree(response.body());}
    private List<Integer> race(Callable<Integer> a,Callable<Integer> b)throws Exception{var pool=Executors.newFixedThreadPool(2);var go=new CountDownLatch(1);try{var aa=pool.submit(()->{go.await();return a.call();});var bb=pool.submit(()->{go.await();return b.call();});go.countDown();return List.of(aa.get(30,TimeUnit.SECONDS),bb.get(30,TimeUnit.SECONDS));}finally{pool.shutdownNow();}}
    private void execute(String query)throws Exception{try(var s=sql.createStatement()){s.execute(query);}}
    private long count(String query)throws Exception{try(var s=sql.createStatement();var r=s.executeQuery(query)){r.next();return r.getLong(1);}}
    private String url(){return System.getenv("BSIC_MIGRATION_TEST_URL");}private String user(){return System.getenv().getOrDefault("BSIC_MIGRATION_TEST_USERNAME","postgres");}private String password(){return System.getenv().getOrDefault("BSIC_MIGRATION_TEST_PASSWORD","");}
